import numpy as np

class PopulationIteratedLocalSearch:
    def __init__(self, budget=10000, dim=10, pop_size=20, local_search_iterations=10, reinit_threshold=0.2):
        self.budget = budget
        self.dim = dim
        self.pop_size = pop_size
        self.local_search_iterations = local_search_iterations
        self.reinit_threshold = reinit_threshold

    def __call__(self, func):
        self.f_opt = np.inf
        self.x_opt = None
        self.pop = np.random.uniform(func.bounds.lb, func.bounds.ub, size=(self.pop_size, self.dim))
        self.fitness = np.array([func(x) for x in self.pop])
        self.budget -= self.pop_size

        if np.min(self.fitness) < self.f_opt:
            self.f_opt = np.min(self.fitness)
            self.x_opt = self.pop[np.argmin(self.fitness)]

        while self.budget > 0:
            # Local Search
            for i in range(self.pop_size):
                if self.budget <= 0:
                    break
                for _ in range(min(self.local_search_iterations, self.budget)):
                    if self.budget <= 0:
                        break
                    perturbation = np.random.normal(0, 0.05, size=self.dim)
                    x_local = np.clip(self.pop[i] + perturbation, func.bounds.lb, func.bounds.ub)
                    f_local = func(x_local)
                    self.budget -= 1

                    if f_local < self.fitness[i]:
                        self.pop[i] = x_local
                        self.fitness[i] = f_local

                        if f_local < self.f_opt:
                            self.f_opt = f_local
                            self.x_opt = x_local

            # Re-initialization
            fitness_threshold = np.mean(self.fitness) + self.reinit_threshold * np.std(self.fitness)
            for i in range(self.pop_size):
                if self.fitness[i] > fitness_threshold:
                    self.pop[i] = np.random.uniform(func.bounds.lb, func.bounds.ub, size=self.dim)
                    self.fitness[i] = func(self.pop[i])
                    self.budget -= 1
                    if self.fitness[i] < self.f_opt:
                        self.f_opt = self.fitness[i]
                        self.x_opt = self.pop[i]

        return self.f_opt, self.x_opt

